Jellyfin Gateway.GATEWAY_CONFIG:
{
  admin off
  # Jellyfin accepts session tokens as ?api_key= and in X-Emby-* headers, and
  # Caddy's error log records the request URI and headers. Caddy already
  # redacts Authorization and Cookie.
  log {
    format filter {
      request>uri regexp [?].* ?[redacted]
      request>headers>Referer delete
      request>headers>X-Emby-Token delete
      request>headers>X-Emby-Authorization delete
      request>headers>X-Mediabrowser-Token delete
      resp_headers>Location delete
    }
  }
}
:8080 {
  handle /healthz {
    rewrite * /health
    reverse_proxy http://__JELLYFIN__
  }
  handle /files* {
    basic_auth {
      __USERNAME__ __PASSWORD_HASH__
    }
    reverse_proxy http://__UPLOADS__ {
      header_up -Authorization
    }
  }
  handle {
    reverse_proxy http://__JELLYFIN__ {
      header_up X-Forwarded-For {http.request.header.X-Real-IP}
      header_up X-Forwarded-Proto {http.request.header.X-Forwarded-Proto}
      header_up -Forwarded
    }
  }
}
